import re

class JSONParseError(ValueError):
    """Exception raised for errors in the JSON parsing process."""
    pass

def parse_json(json_str):
    """
    Parse a JSON string according to RFC 8259 without using the built‑in json module
    or eval. Returns the corresponding Python data structure or raises JSONParseError.
    """
    # ----------------------------------------------------------------------
    # Token definitions
    # ----------------------------------------------------------------------
    _WHITESPACE = re.compile(r'[ \t\r\n]*')
    _STRING = re.compile(r'"(?:\\["\\/bfnrt]|\\u[0-9a-fA-F]{4}|[^"\\])*"')
    _NUMBER = re.compile(r'-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?')
    _TRUE   = re.compile(r'true')
    _FALSE  = re.compile(r'false')
    _NULL   = re.compile(r'null')
    _LBRACE = re.compile(r'\{')
    _RBRACE = re.compile(r'\}')
    _LBRACK = re.compile(r'\[')
    _RBRACK = re.compile(r'\]')
    _COMMA  = re.compile(r',')
    _COLON  = re.compile(r':')

    # ----------------------------------------------------------------------
    # Escape handling for strings
    # ----------------------------------------------------------------------
    _ESCAPE_RE = re.compile(r'\\(["\\/bfnrt])|\\u([0-9a-fA-F]{4})')
    _ESCAPE_MAP = {
        '"': '"', '\\': '\\', '/': '/', 'b': '\b',
        'f': '\f', 'n': '\n', 'r': '\r', 't': '\t'
    }

    def _decode_string(raw):
        """Decode JSON escape sequences, raw includes surrounding quotes."""
        def repl(m):
            if m.group(1):
                return _ESCAPE_MAP[m.group(1)]
            return chr(int(m.group(2), 16))
        return _ESCAPE_RE.sub(repl, raw[1:-1])

    # ----------------------------------------------------------------------
    # Token generator
    # ----------------------------------------------------------------------
    def _tokenize(s):
        pos = 0
        length = len(s)
        while pos < length:
            # Skip any whitespace before the next token
            m_ws = _WHITESPACE.match(s, pos)
            pos = m_ws.end()
            if pos >= length:
                break

            # Try each token regex in order
            for typ, regex in (
                ('string', _STRING),
                ('number', _NUMBER),
                ('true',   _TRUE),
                ('false',  _FALSE),
                ('null',   _NULL),
                ('lbrace', _LBRACE),
                ('rbrace', _RBRACE),
                ('lbracket', _LBRACK),
                ('rbracket', _RBRACK),
                ('comma',  _COMMA),
                ('colon',  _COLON),
            ):
                m = regex.match(s, pos)
                if m:
                    yield typ, m.group(0)
                    pos = m.end()
                    break
            else:
                raise JSONParseError(f'Invalid token at position {pos}')
        yield 'eof', ''

    # ----------------------------------------------------------------------
    # Recursive‑descent parser
    # ----------------------------------------------------------------------
    class _Parser:
        def __init__(self, text):
            self.tokens = _tokenize(text)
            self.tok_type, self.tok_val = next(self.tokens)

        def _advance(self):
            self.tok_type, self.tok_val = next(self.tokens)

        def _expect(self, typ):
            if self.tok_type != typ:
                raise JSONParseError(f'Expected {typ} but found {self.tok_type}')
            val = self.tok_val
            self._advance()
            return val

        def parse(self):
            value = self._value()
            if self.tok_type != 'eof':
                raise JSONParseError('Extra data after valid JSON')
            return value

        def _value(self):
            if self.tok_type == 'string':
                s = _decode_string(self.tok_val)
                self._advance()
                return s
            if self.tok_type == 'number':
                num_str = self.tok_val
                self._advance()
                return float(num_str) if ('.' in num_str or 'e' in num_str or 'E' in num_str) else int(num_str)
            if self.tok_type == 'true':
                self._advance()
                return True
            if self.tok_type == 'false':
                self._advance()
                return False
            if self.tok_type == 'null':
                self._advance()
                return None
            if self.tok_type == 'lbrace':
                return self._object()
            if self.tok_type == 'lbracket':
                return self._array()
            raise JSONParseError(f'Unexpected token {self.tok_type}')

        def _object(self):
            self._expect('lbrace')
            obj = {}
            if self.tok_type == 'rbrace':
                self._advance()
                return obj
            while True:
                if self.tok_type != 'string':
                    raise JSONParseError('Object keys must be strings')
                key = _decode_string(self.tok_val)
                self._advance()
                self._expect('colon')
                value = self._value()
                if key in obj:
                    raise JSONParseError(f'Duplicate key "{key}"')
                obj[key] = value
                if self.tok_type == 'comma':
                    self._advance()
                    continue
                if self.tok_type == 'rbrace':
                    self._advance()
                    break
                raise JSONParseError('Expected , or } in object')
            return obj

        def _array(self):
            self._expect('lbracket')
            arr = []
            if self.tok_type == 'rbracket':
                self._advance()
                return arr
            while True:
                arr.append(self._value())
                if self.tok_type == 'comma':
                    self._advance()
                    continue
                if self.tok_type == 'rbracket':
                    self._advance()
                    break
                raise JSONParseError('Expected , or ] in array')
            return arr

    return _Parser(json_str).parse()

