import re

class JSONParseError(ValueError):
    pass

def parse_json(json_str):
    """
    Parse a JSON string according to RFC 8259 without using the built‑in json module
    or eval. Returns the corresponding Python data structure or raises JSONParseError.
    """
    # Token patterns
    _WHITESPACE = re.compile(r'\s*', re.ASCII)
    _STRING = re.compile(r'"(?:[^"\\\x00-\x1F]|\\["\\/bfnrt]|\\u[0-9a-fA-F]{4})*"')
    _NUMBER = re.compile(r'-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?')
    _TRUE = re.compile(r'true')
    _FALSE = re.compile(r'false')
    _NULL = re.compile(r'null')
    _LBRACE = re.compile(r'\{')
    _RBRACE = re.compile(r'\}')
    _LBRACK = re.compile(r'\[')
    _RBRACK = re.compile(r'\]')
    _COMMA = re.compile(r',')
    _COLON = re.compile(r':')

    # Helper to skip whitespace and return next token regex match
    def _skip_ws(pos):
        m = _WHITESPACE.match(json_str, pos)
        return m.end()

    # Recursive descent parser
    def _parse_value(pos):
        pos = _skip_ws(pos)

        # Try each literal / structure in order of appearance in RFC
        for regex, handler in [
            (_STRING, _parse_string),
            (_NUMBER, _parse_number),
            (_LBRACE, _parse_object),
            (_LBRACK, _parse_array),
            (_TRUE, lambda p: (True, p + 4)),
            (_FALSE, lambda p: (False, p + 5)),
            (_NULL, lambda p: (None, p + 4)),
        ]:
            m = regex.match(json_str, pos)
            if m:
                return handler(pos)

        raise JSONParseError(f'Unexpected token at position {pos}')

    def _parse_string(pos):
        m = _STRING.match(json_str, pos)
        if not m:
            raise JSONParseError(f'Invalid string at position {pos}')
        raw = m.group(0)[1:-1]  # strip surrounding quotes
        # Decode escape sequences
        def _replace_escape(match):
            esc = match.group(0)
            if esc[1] in '"\\/bfnrt':
                return {
                    '"': '"', '\\': '\\', '/': '/', 'b': '\b',
                    'f': '\f', 'n': '\n', 'r': '\r', 't': '\t'
                }[esc[1]]
            # Unicode escape \uXXXX
            return chr(int(esc[2:], 16))
        decoded = re.sub(r'\\(["\\/bfnrt]|u[0-9a-fA-F]{4})', _replace_escape, raw)
        return decoded, m.end()

    def _parse_number(pos):
        m = _NUMBER.match(json_str, pos)
        if not m:
            raise JSONParseError(f'Invalid number at position {pos}')
        num_str = m.group(0)
        # Distinguish int vs float
        if '.' in num_str or 'e' in num_str or 'E' in num_str:
            value = float(num_str)
        else:
            value = int(num_str)
        return value, m.end()

    def _parse_array(pos):
        # Assume '[' already matched
        pos = _skip_ws(pos + 1)  # skip '['
        arr = []
        if json_str[pos:pos+1] == ']':
            return arr, pos + 1
        while True:
            val, pos = _parse_value(pos)
            arr.append(val)
            pos = _skip_ws(pos)
            if json_str[pos:pos+1] == ',':
                pos = _skip_ws(pos + 1)
                continue
            if json_str[pos:pos+1] == ']':
                return arr, pos + 1
            raise JSONParseError(f'Expected , or ] in array at position {pos}')

    def _parse_object(pos):
        # Assume '{' already matched
        pos = _skip_ws(pos + 1)  # skip '{'
        obj = {}
        if json_str[pos:pos+1] == '}':
            return obj, pos + 1
        while True:
            # key must be a string
            key, pos = _parse_string(pos)
            pos = _skip_ws(pos)
            if json_str[pos:pos+1] != ':':
                raise JSONParseError(f'Expected : after object key at position {pos}')
            pos = _skip_ws(pos + 1)  # skip ':'
            val, pos = _parse_value(pos)
            obj[key] = val
            pos = _skip_ws(pos)
            if json_str[pos:pos+1] == ',':
                pos = _skip_ws(pos + 1)
                continue
            if json_str[pos:pos+1] == '}':
                return obj, pos + 1
            raise JSONParseError(f'Expected , or }} in object at position {pos}')

    # Start parsing
    result, end = _parse_value(0)
    end = _skip_ws(end)
    if end != len(json_str):
        raise JSONParseError(f'Extra data after valid JSON at position {end}')
    return result

