        def replace_escape(match):
            esc = match.group(0)
            if esc[1] in '"\\/bfnrt':
                return {
                    '"': '"', '\\': '\\', '/': '/', 'b': '\b',
                    'f': '\f', 'n': '\n', 'r': '\r', 't': '\t'
                }[esc[1]]
