        if s[pos] != '[':
            raise JSONParseError(f'Expected "[" at position {pos}')
        pos += 1
        arr = []
        pos = skip_ws(pos)
        if pos < n and s[pos] == ']':
            return pos + 1, arr  # empty array

        while True:
            pos, value = parse_value(pos)
            arr.append(value)
            pos = skip_ws(pos)
            if pos >= n:
                raise JSONParseError('Unexpected end of input in array')
            if s[pos] == ',':
                pos += 1
                continue
            if s[pos] == ']':
                return pos + 1, arr
            raise JSONParseError(f'Expected "," or "]" in array at position {pos}')

    def parse_object(pos):
        """Parse a JSON object."""
        if s[pos] != '{':
            raise JSONParseError(f'Expected "{{" at position {pos}')
        pos += 1
        obj = {}
        pos = skip_ws(pos)
        if pos < n and s[pos] == '}':
