        while i < n and s[i] in _WHITESPACE:
            i += 1

    def error(msg):
        raise ValueError(f'Error at position {i}: {msg}')

    # ---------- literals ----------
    def parse_literal(lit, value):
        nonlocal i
        if s.startswith(lit, i):
            i += len(lit)
            return value
        error(f'Expected literal {lit}')

    # ---------- number ----------
    def parse_number():
        nonlocal i
        start = i
        # optional minus
        if s[i] == '-':
            i += 1
            if i >= n:
                error('Minus sign without digits')
        # integer part
        if i < n and s[i] == '0':
            i += 1
        else:
            if i >= n or not s[i].isdigit():
                error('Invalid number')
            while i < n and s[i].isdigit():
                i += 1
        # fraction
        if i < n and s[i] == '.':
            i += 1
            if i >= n or not s[i].isdigit():
                error('Fraction part requires at least one digit')
            while i < n and s[i].isdigit():
                i += 1
