        if i < n and s[i] in 'eE':
            i += 1
            if i < n and s[i] in '+-':
                i += 1
            if i >= n or not s[i].isdigit():
                error('Exponent part requires at least one digit')
            while i < n and s[i].isdigit():
                i += 1
