        if not _NUMBER_RE.match(num_str):
            error('Malformed number')
        return float(num_str) if any(c in num_str for c in '.eE') else int(num_str)

    # ---------- string ----------
    def parse_string():
        nonlocal i
        if s[i] != '"':
            error('String must start with a double quote')
        i += 1  # skip opening quote
        result = []
