                error('Unterminated array')
            if s[i] == ',':
                i += 1
                skip_ws()
                if i < n and s[i] == ']':
                    error('Trailing comma in array')
                continue
            if s[i] == ']':
                i += 1
                return arr
            error(f'Expected , or ] in array, got {s[i]!r}')

    # ---------- object ----------
    def parse_object():
        nonlocal i
        if s[i] != '{':
            error('Object must start with {')
        i += 1
        skip_ws()
        obj = {}
        if i < n and s[i] == '}':
            i += 1
            return obj
        while True:
            skip_ws()
            if i >= n or s[i] != '"':
                error('Object keys must be strings')
            key = parse_string()
            skip_ws()
            if i >= n or s[i] != ':':
                error('Missing colon after object key')
            i += 1
            skip_ws()
            value = parse_value()
            if key in obj:
                error(f'Duplicate key {key!r} in object')
            obj[key] = value
            skip_ws()
            if i >= n:
                error('Unterminated object')
            if s[i] == ',':
                i += 1
                skip_ws()
                if i < n and s[i] == '}':
                    error('Trailing comma in object')
                continue
            if s[i] == '}':
                i += 1
                return obj
            error(f'Expected , or }} in object, got {s[i]!r}')

    # ---------- value ----------
    def parse_value():
        skip_ws()
        if i >= n:
            error('Unexpected end of input while expecting a value')
        ch = s[i]
        if ch == '"':
            return parse_string()
        if ch == '{':
            return parse_object()
        if ch == '[':
            return parse_array()
        if ch == 't':
            return parse_literal('true', True)
        if ch == 'f':
            return parse_literal('false', False)
        if ch == 'n':
            return parse_literal('null', None)
        if ch == '-' or ch.isdigit():
            return parse_number()
        error(f'Invalid character {ch!r} starting a value')

    # ---------- entry ----------
    result = parse_value()
    skip_ws()
    if i != n:
        error('Extra data after valid JSON value')
    return result

