    # Parse an array starting with '['
    def _parse_array(i):
        i = _skip_ws(i)
        if json_str[i] != '[':
            raise ValueError(f"Expected '[' at position {i}")
        i += 1  # skip '['
        arr = []
        i = _skip_ws(i)
        if i < len(json_str) and json_str[i] == ']':
            return arr, i + 1  # empty array

        while True:
            value, i = _parse_value(i)
