    result, end = _parse_value(0)
    end = _skip_ws(end)
    if end != len(json_str):
        raise ValueError(f"Extra data after valid JSON at position {end}")
    return result

def parse_json(json_str):
    """
    Minimal JSON parser conforming to RFC 8259.
    Supports objects, arrays, strings, numbers, true, false, null.
    Raises ValueError on any syntax error.
    """
    import re

    # Regex patterns for number validation (RFC 8259)
    _NUMBER_RE = re.compile(
        r'-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?'
    )
    _WHITESPACE = {' ', '\t', '\n', '\r'}

    s = json_str
    i = 0
    n = len(s)

    def error(msg):
        raise ValueError(f"{msg} at position {i}")

    def skip_ws():
        nonlocal i
        while i < n and s[i] in _WHITESPACE:
            i += 1

    def peek():
        return s[i] if i < n else ''

    def consume(expected):
        nonlocal i
        if peek() != expected:
            error(f"Expected '{expected}'")
        i += 1

    def parse_value():
        skip_ws()
        ch = peek()
        if ch == '"':
            return parse_string()
        elif ch == '{':
            return parse_object()
        elif ch == '[':
            return parse_array()
        elif ch in '-0123456789':
            return parse_number()
        elif s.startswith('true', i):
            i_ = i
            i += 4
            return True
        elif s.startswith('false', i):
            i_ = i
            i += 5
            return False
        elif s.startswith('null', i):
            i_ = i
            i += 4
            return None
        else:
            error("Unexpected character")

    def parse_string():
        nonlocal i
        consume('"')
        result = []
        while True:
            if i >= n:
                error("Unterminated string")
            ch = s[i]
            if ch == '"':
                i += 1
                return ''.join(result)
            if ch == '\\':
                i += 1
                if i >= n:
                    error("Unterminated escape sequence")
                esc = s[i]
                if esc == '"':
                    result.append('"')
                elif esc == '\\':
                    result.append('\\')
                elif esc == '/':
                    result.append('/')
                elif esc == 'b':
                    result.append('\b')
                elif esc == 'f':
                    result.append('\f')
                elif esc == 'n':
                    result.append('\n')
                elif esc == 'r':
                    result.append('\r')
                elif esc == 't':
                    result.append('\t')
                elif esc == 'u':
                    # Expect four hex digits
                    if i + 4 >= n:
                        error("Invalid \\u escape")
                    hex_digits = s[i+1:i+5]
                    if not all(c in "0123456789abcdefABCDEF" for c in hex_digits):
                        error("Invalid \\u escape")
                    code_point = int(hex_digits, 16)
                    result.append(chr(code_point))
                    i += 4
                else:
                    error(f"Invalid escape character '\\{esc}'")
                i += 1
            else:
                # JSON strings must not contain control characters (U+0000 through U+001F)
                if ord(ch) < 0x20:
                    error("Invalid control character in string")
                result.append(ch)
                i += 1

    def parse_number():
        nonlocal i
        start = i
        while i < n and s[i] in '-0123456789+eE.':
            i += 1
        num_str = s[start:i]
        if not _NUMBER_RE.fullmatch(num_str):
            error(f"Invalid number '{num_str}'")
        # Distinguish int vs float
        if '.' in num_str or 'e' in num_str or 'E' in num_str:
            return float(num_str)
        else:
            return int(num_str)

    def parse_array():
        nonlocal i
        consume('[')
        skip_ws()
        arr = []
        if peek() == ']':
            i += 1
            return arr
        while True:
            arr.append(parse_value())
            skip_ws()
            ch = peek()
            if ch == ',':
                i += 1
                continue
            if ch == ']':
                i += 1
                return arr
            error("Expected ',' or ']' in array")

    def parse_object():
        nonlocal i
        consume('{')
        skip_ws()
        obj = {}
        if peek() == '}':
            i += 1
            return obj
        while True:
            skip_ws()
            if peek() != '"':
                error("Object keys must be strings")
            key = parse_string()
            skip_ws()
            consume(':')
            value = parse_value()
            if key in obj:
                error(f"Duplicate key '{key}'")
            obj[key] = value
            skip_ws()
            ch = peek()
            if ch == ',':
                i += 1
                continue
            if ch == '}':
                i += 1
                return obj
            error("Expected ',' or '}' in object")

    result = parse_value()
    skip_ws()
    if i != n:
        error("Trailing data after valid JSON")
    return result

