    _WHITESPACE = re.compile(r'\s*', re.ASCII)
    _STRING_RE = re.compile(r'"(?:\\["\\/bfnrt]|\\u[0-9a-fA-F]{4}|[^"\\])*"', re.ASCII)
    _NUMBER_RE = re.compile(r'-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?', re.ASCII)

    # Helper to skip whitespace and return next position
    def _skip_ws(i):
        m = _WHITESPACE.match(json_str, i)
        return m.end()

    # Parse a JSON value starting at index i, return (value, new_index)
    def _parse_value(i):
        i = _skip_ws(i)
        if i >= len(json_str):
            raise ValueError("Unexpected end of input while parsing value")

        ch = json_str[i]

        if ch == '"':                     # string
            m = _STRING_RE.match(json_str, i)
            if not m:
                raise ValueError(f"Invalid string at position {i}")
            raw = m.group(0)
            # Decode escape sequences
            s = _decode_string(raw[1:-1])
            return s, m.end()

        if ch == '{':                     # object
            return _parse_object(i)

        if ch == '[':                     # array
            return _parse_array(i)

        if json_str.startswith('true', i):
            return True, i + 4
        if json_str.startswith('false', i):
            return False, i + 5
        if json_str.startswith('null', i):
            return None, i + 4

        # number
        m = _NUMBER_RE.match(json_str, i)
        if m:
            num_str = m.group(0)
            if '.' in num_str or 'e' in num_str or 'E' in num_str:
                num = float(num_str)
            else:
                num = int(num_str)
            return num, m.end()

        raise ValueError(f"Unexpected character '{ch}' at position {i}")

    # Decode JSON string escapes
    def _decode_string(s):
        # Replace known escapes
        esc_map = {
            '"': '"',
            '\\': '\\',
            '/': '/',
            'b': '\b',
            'f': '\f',
            'n': '\n',
            'r': '\r',
            't': '\t',
        }

        def replace(match):
            seq = match.group(0)
            if seq[1] in esc_map:
                return esc_map[seq[1]]
            if seq[1] == 'u':
                return chr(int(seq[2:], 16))
            # Should never reach here because regex guarantees valid escapes
            return seq

        return re.sub(r'\\(["\\/bfnrt]|u[0-9a-fA-F]{4})', replace, s)

    # Parse an object starting with '{'
    def _parse_object(i):
        i = _skip_ws(i)
        if json_str[i] != '{':
            raise ValueError(f"Expected '{{' at position {i}")
        i += 1  # skip '{'
        obj = {}
        i = _skip_ws(i)
        if i < len(json_str) and json_str[i] == '}':
            return obj, i + 1  # empty object

        while True:
            i = _skip_ws(i)
            # key must be a string
            if i >= len(json_str) or json_str[i] != '"':
                raise ValueError(f"Expected string key at position {i}")
            key, i = _parse_value(i)   # reuse string parser
            if not isinstance(key, str):
                raise ValueError(f"Object key must be string at position {i}")

            i = _skip_ws(i)
            if i >= len(json_str) or json_str[i] != ':':
                raise ValueError(f"Expected ':' after key at position {i}")
            i += 1  # skip ':'

            value, i = _parse_value(i)
            obj[key] = value

            i = _skip_ws(i)
            if i >= len(json_str):
                raise ValueError("Unexpected end of input in object")
            if json_str[i] == '}':
                return obj, i + 1
            if json_str[i] != ',':
                raise ValueError(f"Expected ',' or '}}' in object at position {i}")
            i += 1  # skip ',' and continue

    # Parse an array starting with '['
    def _parse_array(i):
        i = _skip_ws(i)
        if json_str[i] != '[':
            raise ValueError(f"Expected '[' at position {i}")
        i += 1  # skip '['
        arr = []
        i = _skip_ws(i)
        if i < len(json_str) and json_str[i] == ']':
            return arr, i + 1  # empty array

        while True:
            value, i = _parse_value(i)
            arr.append(value)

            i = _skip_ws(i)
            if i >= len(json_str):
                raise ValueError("Unexpected end of input in array")
            if json_str[i] == ']':
                return arr, i + 1
            if json_str[i] != ',':
                raise ValueError(f"Expected ',' or ']' in array at position {i}")
            i += 1  # skip ',' and continue

