    import re

    # Regex patterns for tokens
    _WHITESPACE = re.compile(r'\s*', re.ASCII)
    _NUMBER = re.compile(
        r'-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?', re.ASCII)

    # Helper to skip whitespace and return next position
    def _skip_ws(i):
        m = _WHITESPACE.match(json_str, i)
        return m.end()

    # Parse a JSON value starting at index i, return (value, new_index)
    def _parse_value(i):
        i = _skip_ws(i)
        if i >= len(json_str):
            raise ValueError("Unexpected end of input while parsing value")

        ch = json_str[i]

        if ch == '"':
            return _parse_string(i)
        if ch == '{':
            return _parse_object(i)
        if ch == '[':
            return _parse_array(i)
        if ch in '-0123456789':
            return _parse_number(i)
        if json_str.startswith('true', i):
            return True, i + 4
        if json_str.startswith('false', i):
            return False, i + 5
        if json_str.startswith('null', i):
            return None, i + 4

        raise ValueError(f"Invalid token at position {i}: {json_str[i:i+10]!r}")

    # Parse a JSON string (starting with a double quote)
    def _parse_string(i):
        i += 1  # skip opening quote
        start = i
        result = []
        while i < len(json_str):
            ch = json_str[i]
            if ch == '"':
                result.append(json_str[start:i])
                return ''.join(result), i + 1
            if ch == '\\':
                # Append any characters before the backslash
                result.append(json_str[start:i])
                i += 1
                if i >= len(json_str):
                    raise ValueError("Unterminated escape sequence in string")
                esc = json_str[i]
                if esc == '"':
                    result.append('"')
                elif esc == '\\':
                    result.append('\\')
                elif esc == '/':
                    result.append('/')
                elif esc == 'b':
                    result.append('\b')
                elif esc == 'f':
                    result.append('\f')
                elif esc == 'n':
                    result.append('\n')
                elif esc == 'r':
                    result.append('\r')
                elif esc == 't':
                    result.append('\t')
                elif esc == 'u':
                    # Unicode escape: exactly four hex digits
                    if i + 4 >= len(json_str):
                        raise ValueError("Incomplete \\u escape")
                    hex_digits = json_str[i+1:i+5]
                    if not re.fullmatch(r'[0-9a-fA-F]{4}', hex_digits):
                        raise ValueError(f"Invalid \\u escape: {hex_digits}")
                    result.append(chr(int(hex_digits, 16)))
                    i += 4
                else:
                    raise ValueError(f"Invalid escape character '\\{esc}'")
                i += 1
                start = i
                continue
            # Normal character
            i += 1
        raise ValueError("Unterminated string literal")

    # Parse a JSON number
    def _parse_number(i):
        m = _NUMBER.match(json_str, i)
        if not m:
            raise ValueError(f"Invalid number at position {i}")
        num_str = m.group(0)
        i = m.end()
        # Distinguish int vs float
        if any(c in num_str for c in '.eE'):
            return float(num_str), i
        else:
            return int(num_str), i

    # Parse a JSON array
    def _parse_array(i):
        i += 1  # skip '['
        arr = []
        i = _skip_ws(i)
        if i < len(json_str) and json_str[i] == ']':
            return arr, i + 1  # empty array
        while True:
            val, i = _parse_value(i)
            arr.append(val)
            i = _skip_ws(i)
            if i >= len(json_str):
                raise ValueError("Unterminated array")
            if json_str[i] == ',':
                i += 1
                continue
            if json_str[i] == ']':
                return arr, i + 1
            raise ValueError(f"Expected ',' or ']' in array at position {i}")

    # Parse a JSON object
    def _parse_object(i):
        i += 1  # skip '{'
        obj = {}
        i = _skip_ws(i)
        if i < len(json_str) and json_str[i] == '}':
            return obj, i + 1  # empty object
        while True:
            i = _skip_ws(i)
            if i >= len(json_str) or json_str[i] != '"':
                raise ValueError(f"Expected string key at position {i}")
            key, i = _parse_string(i)
            i = _skip_ws(i)
            if i >= len(json_str) or json_str[i] != ':':
                raise ValueError(f"Expected ':' after key at position {i}")
            i += 1
            value, i = _parse_value(i)
            if key in obj:
                raise ValueError(f"Duplicate key '{key}' in object")
            obj[key] = value
            i = _skip_ws(i)
            if i >= len(json_str):
                raise ValueError("Unterminated object")
            if json_str[i] == ',':
                i += 1
                continue
            if json_str[i] == '}':
                return obj, i + 1
            raise ValueError(f"Expected ',' or '}' in object at position {i}")

    # Entry point
    value, end = _parse_value(0)
    end = _skip_ws(end)
    if end != len(json_str):
        raise ValueError(f"Extra data after valid JSON at position {end}")
    return value

