            if self.current == 'FALSE':
                self._advance()
                return False
            if self.current == 'NULL':
                self._advance()
                return None
            _error("Unexpected token", self.lexer.i)

        def _object(self):
            obj = {}
            self._expect('{')
            if self.current == '}':
                self._expect('}')
                return obj
