        raise ValueError(f"{msg} at position {pos}")

    # ----------------------------------------------------------------------
    # Lexer
    # ----------------------------------------------------------------------
    class _Lexer:
        def __init__(self, s):
            self.s = s
            self.i = 0
            self.n = len(s)

