            self._skip_ws()
            return self.s[self.i] if self.i < self.n else ''

        def consume(self, expected=None):
            if self.i >= self.n:
                _error("Unexpected end of input", self.i)
            ch = self.s[self.i]
            if expected and ch != expected:
