            self._skip_ws()
            m = pattern.match(self.s, self.i)
            if m:
                self.i = m.end()
                return m.group()
            return None

        # ------------------------------------------------------------------
        # Token readers
        # ------------------------------------------------------------------
        def read_string(self):
            self.consume('"')
            result = []
            while True:
                if self.i >= self.n:
                    _error("Unterminated string", self.i)
                ch = self.consume()
                if ch == '"':
                    break
                if ch == '\\':
                    if self.i >= self.n:
                        _error("Unterminated escape sequence", self.i)
                    esc = self.consume()
