            if self.i >= self.n:
                return None, None
            ch = self.s[self.i]

            # Single‑character tokens
            if ch in '{[]}:,':
                self.i += 1
                return ch, ch

            # Literals
            if self.s.startswith('true', self.i):
                self.i += 4
                return 'TRUE', True
            if self.s.startswith('false', self.i):
                self.i += 5
                return 'FALSE', False
            if self.s.startswith('null', self.i):
                self.i += 4
                return 'NULL', None

            # Number
            if ch == '-' or ch.isdigit():
                return 'NUMBER', self.read_number()

            # String
            if ch == '"':
                return 'STRING', self.read_string()

            _error(f"Invalid character '{ch}'", self.i)

    # ----------------------------------------------------------------------
    # Parser
    # ----------------------------------------------------------------------
    class _Parser:
        def __init__(self, lexer):
            self.lexer = lexer
            self.current, self.value = self.lexer.next_token()

        def _advance(self):
            self.current, self.value = self.lexer.next_token()

        def parse(self):
