        def _array(self):
            arr = []
            self._expect('[')
            if self.current == ']':
                self._expect(']')
                return arr
            while True:
                arr.append(self._value())
                if self.current == ']':
                    self._expect(']')
                    break
                self._expect(',')
            return arr

