            esc = match.group(0)
            if esc[1] in '"\\/bfnrt':
                return {
                    '"': '"', '\\': '\\', '/': '/', 'b': '\b',
                    'f': '\f', 'n': '\n', 'r': '\r', 't': '\t'
                }[esc[1]]
            # unicode escape \uXXXX
            return chr(int(esc[2:], 16))
        return re.sub(r'\\(["\\/bfnrt]|u[0-9a-fA-F]{4})', replace, s)

