    def _parse_value(i):
        i = _skip_ws(i)
        if i >= len(json_str):
            raise ValueError("Unexpected end of input")

        ch = json_str[i]

        if ch == '{':
            return _parse_object(i)
        if ch == '[':
            return _parse_array(i)
        if ch == '"':
            m = _STRING.match(json_str, i)
            if not m:
                raise ValueError(f"Invalid string at position {i}")
            raw = m.group(0)[1:-1]  # strip quotes
