            m = _NUMBER.match(json_str, i)
            if not m:
                raise ValueError(f"Invalid number at position {i}")
            num_str = m.group(0)
            # decide int vs float
            if '.' in num_str or 'e' in num_str or 'E' in num_str:
                return float(num_str), m.end()
            else:
                return int(num_str), m.end()
        if json_str.startswith('true', i):
            return True, i + 4
        if json_str.startswith('false', i):
