            if ch == '[':
                return self._array()
            if ch == 't':
                return self._literal(_TRUE, True)
            if ch == 'f':
                return self._literal(_FALSE, False)
            if ch == 'n':
                return self._literal(_NULL, None)
            if ch == '-' or ch.isdigit():
                return self._number()
            raise ValueError(f"Unexpected character '{ch}' at position {self.i}")

        def _literal(self, pattern, value):
            m = pattern.match(self.s, self.i)
            if not m:
                raise ValueError(f"Invalid literal at position {self.i}")
            self.i = m.end()
            return value

        def _number(self):
            m = _NUMBER.match(self.s, self.i)
            if not m:
                raise ValueError(f"Invalid number at position {self.i}")
            num_str = m.group()
            self.i = m.end()
